input.command:
cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

// Observable failure contract adopted for this run: the specification says only
// that "the CLI exits with a non-zero status code and writes an error
// description to stderr". The most defensible reading is that the domain layer
// signals rejection by throwing an `Error` (no type or message is established
// by the specification) and the CLI adapter translates that into exit code 1
// plus a stderr message. Domain tests therefore assert "throws an Error"; the
// CLI tests assert the non-zero exit status and non-empty stderr.

describe("MHPCO Claim Office", () => {
  // --- Quote: simplest case and the price list ---
  it.todo("quotes an empty item list as 5 G (processing fee only)");
  it.todo("quotes a single plain sword as 115 G (100 base + 10 first insurance + 5 fee)");
  it.todo("quotes a single plain amulet as 71 G (60 base + 6 first insurance + 5 fee)");
  it.todo("quotes a single plain staff as 93 G (80 base + 8 first insurance + 5 fee)");
  it.todo("quotes a single plain potion as 49 G (40 base + 4 first insurance + 5 fee)");
  it.todo("quotes a single rune at base premium 25 G");
  it.todo("quotes a single moonstone at base premium 25 G");
  it.todo("rejects a quote item with an unknown type (e.g. broomstick) by throwing an Error");

  // --- Component building blocks ---
  it.todo("quotes 2 runes at base premium 50 G (no block)");
  it.todo("quotes 3 runes at base premium 60 G (block applies)");
  it.todo("quotes 4 runes at base premium 100 G (no block -- block requires exactly 3)");
  it.todo("quotes 7 runes at base premium 175 G (no block -- block requires exactly 3)");
  it.todo("quotes 2 runes + 1 moonstone at base premium 75 G (no block: different types)");
  it.todo("quotes 3 runes + 3 moonstones at base premium 120 G (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("adds a 50% curse surcharge to the cursed item's base premium only (cursed sword + plain amulet: 160 base + 50 = 210 before policy modifiers and fee)");
  it.todo("adds a 30% high-enchantment surcharge for enchantment exactly 5 (sword: 100 base + 30)");
  it.todo("adds no high-enchantment surcharge for enchantment 4 (sword: 100 base)");
  it.todo("adds both surcharges to a cursed sword with enchantment 5 (100 base + 50 curse + 30 enchantment = 180)");

  // --- Policy-wide modifiers ---
  it.todo("applies a 20% loyalty discount for a customer with exactly 2 years with MHPCO (sword: 100 base - 20)");
  it.todo("applies no loyalty discount for a customer with 1 year with MHPCO (sword: 100 base)");
  it.todo("applies a 15% follow-up discount to every quote after the first in a scenario (second plain sword quote: 100 base + 10 first insurance - 15 follow-up + 5 fee = 100 G)");

  // --- Premium rounding ---
  it.todo("rounds a premium of 197.5 G up to 198 G (in MHPCO's favor)");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("pays out 400 G for a regular steel sword with enchantment 3 damaged by 500 G (500 - 100 deductible)");
  it.todo("pays out 100 G for a damaged rune (damage 200 G, no enchantment or material, 200 - 100)");
  it.todo("reports the remaining cap after a claim (sword policy, cap 2000 G, payout 400 G -> remainingCap 1600 G)");
  it.todo("applies the 100 G deductible once per damaged item (sword 500 G + amulet 300 G -> payout 600 G)");

  // --- Claim: special clauses ---
  it.todo("reimburses 50% of the damage for enchantment >= 8 (steel sword, enchantment 9, damage 1000 G -> payout 400 G)");
  it.todo("reimburses a dragon-material sword in full (dragon sword, enchantment 5, damage 800 G -> payout 700 G)");
  it.todo("lets the 50% high-enchantment rule win over dragon material (dragon sword, enchantment 9, damage 1000 G -> payout 400 G)");

  // --- Claim: insurance sum and cap ---
  it.todo("caps the payout at twice the insurance sum across successive claims (sword policy, cap 2000 G; 1500 G claim -> payout 1400 G, remainingCap 600 G; second 1500 G claim -> payout 600 G, remainingCap 0 G)");
  it.todo("computes the insurance sum of a sword plus an amulet as 1600 G (cap 3200 G)");
  it.todo("bases the cap on unmodified insurance values (cursed sword, premium 165 G -> cap 2000 G)");
  it.todo("excludes the block discount from the insurance sum (sword + 3 runes -> insurance sum 1750 G, cap 3500 G)");

  // --- Claim: multiple items of the same type ---
  it.todo("insures two swords with an insurance sum of 2000 G (cap 4000 G)");
  it.todo("treats two sword damage entries as separate damages with their own deductible (two swords insured, 500 G each -> payout 800 G)");
  it.todo("rejects a claim with more damage entries of a type than the policy covers (two sword damages, one sword insured) by throwing an Error");

  // --- Claim: rejections and rounding ---
  it.todo("rejects a claim for an item that is not part of the policy (amulet damaged, only a sword insured) by throwing an Error");
  it.todo("rejects a claim damage entry with an unknown item type by throwing an Error");
  it.todo("rejects a claim damage entry with a negative amount (-200) by throwing an Error");
  it.todo("rounds a payout of 350.5 G down to 350 G (in MHPCO's favor)");

  // --- CLI adapter ---
  it.todo("CLI reads a scenario from stdin and writes {results:[{premium},{payout,remainingCap}]} to stdout (schema example)");
  it.todo("CLI exits with a non-zero status and writes to stderr for an unknown quote item type, writing no results to stdout");
  it.todo("CLI exits with a non-zero status and writes to stderr for a claim against an item not in the policy");
  it.todo("CLI exits with a non-zero status and writes to stderr for a claim damage amount of -200");

  describe("verification", () => {
    // Combinations expected to pass once their parts exist.
    it.todo("quotes a newcomer's cursed steel sword (enchantment 3, 0 years) as 165 G -- combines curse surcharge, first insurance and fee");
    it.todo("quotes a 3-year customer's second contract for a cursed sword with enchantment 7 as 160 G -- combines curse, high enchantment, loyalty, first insurance and follow-up discount");
    it.todo("pays out 400 G for a dragon sword with exactly enchantment 8 and damage 1000 G -- combines the enchantment-8 threshold with the dragon clause precedence");
    it.todo("keeps intermediate amounts as fractions and rounds only the final premium -- combines percentage modifiers with premium rounding");
    it.todo("quotes a staff and a potion together as 137 G -- combines the price-list entries with the policy-wide first-insurance modifier and fee");
    it.todo("applies the loyalty discount to a policy base that already includes a block discount (3 runes, 2 years: 60 base + 6 - 12 + 5 = 59 G) -- combines blocks with policy-wide modifiers");
    it.todo("pays out for a moonstone damage entry the same way as for a rune (damage 200 G -> 100 G) -- combines the component price list with standard reimbursement");
    it.todo("yields a payout of 0 G when the damage is at or below the deductible (damage 100 G) -- combines deductible subtraction with non-negative payouts");
    it.todo("applies the cap per policy across two different quote steps independently -- combines per-policy cap tracking with multi-step scenarios");
  });
});
EOF
