  1	const PROCESSING_FEE = 5;
  2	const FIRST_INSURANCE_PERCENT = 10;
  3	const PERCENT = 100;
  4	
  5	const INSURANCE_VALUES: Record<string, number> = {
  6	  sword: 1000,
  7	  amulet: 600,
  8	  staff: 800,
  9	  potion: 400,
 10	  rune: 250,
 11	  moonstone: 250,
 12	};
 13	
 14	const CAP_FACTOR = 2;
 15	
 16	const BASE_PREMIUMS: Record<string, number> = {
 17	  sword: 100,
 18	  amulet: 60,
 19	  staff: 80,
 20	  potion: 40,
 21	  rune: 25,
 22	  moonstone: 25,
 23	};
 24	
 25	const COMPONENT_TYPES = ["rune", "moonstone"];
 26	const BLOCK_SIZE = 3;
 27	const BLOCK_BASE_PREMIUM = 60;
 28	const CURSE_PERCENT = 50;
 29	const HIGH_ENCHANTMENT_PERCENT = 30;
 30	const HIGH_ENCHANTMENT_LEVEL = 5;
 31	const LOYALTY_PERCENT = 20;
 32	const LOYALTY_YEARS = 2;
 33	const FOLLOW_UP_PERCENT = 15;
 34	const DEDUCTIBLE = 100;
 35	const REDUCED_REIMBURSEMENT_PERCENT = 50;
 36	const REDUCED_REIMBURSEMENT_LEVEL = 8;
 37	
 38	export interface Item {
 39	  type: string;
 40	  material?: string;
 41	  enchantment?: number;
 42	  cursed?: boolean;
 43	}
 44	
 45	/** Premiums are rounded in the MHPCO's favor, i.e. up. */
 46	function roundPremium(amount: number): number {
 47	  return Math.ceil(amount);
 48	}
 49	
 50	function basePremium(item: Item): number {
 51	  const premium = BASE_PREMIUMS[item.type];
 52	  if (premium === undefined) {
 53	    throw new Error(`MHPCO does not insure items of type "${item.type}"`);
 54	  }
 55	  return premium;
 56	}
 57	
 58	function countsByType(items: Item[]): Map<string, number> {
 59	  const counts = new Map<string, number>();
 60	  for (const item of items) {
 61	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
 62	  }
 63	  return counts;
 64	}
 65	
 66	/**
 67	 * A building block of exactly 3 alike components is offered at a special
 68	 * base premium; otherwise every item is priced from the price list.
 69	 */
 70	function groupBasePremium(type: string, count: number): number {
 71	  const isBuildingBlock = COMPONENT_TYPES.includes(type) && count === BLOCK_SIZE;
 72	  return isBuildingBlock ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
 73	}
 74	
 75	function policyBasePremium(items: Item[]): number {
 76	  items.forEach(basePremium);
 77	  let total = 0;
 78	  for (const [type, count] of countsByType(items)) {
 79	    total += groupBasePremium(type, count);
 80	  }
 81	  return total;
 82	}
 83	
 84	/**
 85	 * Item-specific risk surcharges apply to the base premium of the affected
 86	 * item (reading adopted: its price-list base premium, independent of any
 87	 * building-block discount, which the specification applies to the policy
 88	 * premium only).
 89	 */
 90	function isCursed(item: Item): boolean {
 91	  return item.cursed === true;
 92	}
 93	
 94	function isHighlyEnchanted(item: Item): boolean {
 95	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
 96	}
 97	
 98	function itemSurchargePercent(item: Item): number {
 99	  const curse = isCursed(item) ? CURSE_PERCENT : 0;
100	  const enchantment = isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_PERCENT : 0;
101	  return curse + enchantment;
102	}
103	
104	function itemSurcharges(items: Item[]): number {
105	  return items.reduce(
106	    (sum, item) => sum + (basePremium(item) * itemSurchargePercent(item)) / PERCENT,
107	    0,
108	  );
109	}
110	
111	export interface Customer {
112	  yearsWithMHPCO: number;
113	}
114	
115	function isLongStanding(customer: Customer): boolean {
116	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
117	}
118	
119	const NEW_CUSTOMER: Customer = { yearsWithMHPCO: 0 };
120	
121	/**
122	 * Policy-wide modifiers apply to the policy base premium: an initial
123	 * assessment surcharge on every newly insured item, a loyalty discount for
124	 * long-standing customers, and a discount on each contract after the
125	 * customer's first.
126	 */
127	function policyWideModifiers(policyBase: number, history: CustomerHistory): number {
128	  const firstInsuranceSurcharge = (policyBase * FIRST_INSURANCE_PERCENT) / PERCENT;
129	  const loyaltyDiscount = isLongStanding(history.customer)
130	    ? (policyBase * LOYALTY_PERCENT) / PERCENT
131	    : 0;
132	  const followUpDiscount =
133	    history.previousContracts > 0 ? (policyBase * FOLLOW_UP_PERCENT) / PERCENT : 0;
134	  return firstInsuranceSurcharge - loyaltyDiscount - followUpDiscount;
135	}
136	
137	export interface CustomerHistory {
138	  customer: Customer;
139	  previousContracts: number;
140	}
141	
142	const NEW_CUSTOMER_HISTORY: CustomerHistory = {
143	  customer: NEW_CUSTOMER,
144	  previousContracts: 0,
145	};
146	
147	export function quote(items: Item[], history: CustomerHistory = NEW_CUSTOMER_HISTORY): number {
148	  const policyBase = policyBasePremium(items);
149	  const premium = policyBase + itemSurcharges(items);
150	  return roundPremium(premium + policyWideModifiers(policyBase, history) + PROCESSING_FEE);
151	}
152	
153	export interface QuoteStep {
154	  op: "quote";
155	  items: Item[];
156	}
157	
158	export interface Damage {
159	  itemType: string;
160	  amount: number;
161	}
162	
163	export interface Incident {
164	  cause: string;
165	  damages: Damage[];
166	}
167	
168	export interface ClaimStep {
169	  op: "claim";
170	  policy: number;
171	  incident: Incident;
172	}
173	
174	export type Step = QuoteStep | ClaimStep;
175	
176	export interface Scenario {
177	  customer: Customer;
178	  steps: Step[];
179	}
180	
181	export interface QuoteResult {
182	  premium: number;
183	}
184	
185	export interface ClaimResult {
186	  payout: number;
187	  remainingCap: number;
188	}
189	
190	export type StepResult = QuoteResult | ClaimResult;
191	
192	/** Payouts are rounded in the MHPCO's favor, i.e. down. */
193	function roundPayout(amount: number): number {
194	  return Math.floor(amount);
195	}
196	
197	/**
198	 * Damage to items with enchantment level >= 8 is reimbursed at 50 % of the
199	 * damage amount; otherwise the damage is reimbursed in full.
200	 */
201	function reimbursableDamage(damage: Damage, item: Item): number {
202	  if ((item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_LEVEL) {
203	    return (damage.amount * REDUCED_REIMBURSEMENT_PERCENT) / PERCENT;
204	  }
205	  return damage.amount;
206	}
207	
208	/** A reported damage must name a non-negative amount to be settled. */
209	function validateDamage(damage: Damage): void {
210	  if (damage.amount < 0) {
211	    throw new Error(`A damage amount cannot be negative: ${damage.amount}`);
212	  }
213	}
214	
215	/** A deductible applies per damage event. */
216	function reimbursement(damage: Damage, item: Item): number {
217	  return reimbursableDamage(damage, item) - DEDUCTIBLE;
218	}
219	
220	function insuranceSum(items: Item[]): number {
221	  return items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
222	}
223	
224	/**
225	 * A policy created by a quote step. The total payout per policy is capped at
226	 * twice its insurance sum, so each claim is paid only up to the cap that is
227	 * still available.
228	 */
229	class Policy {
230	  remainingCap: number;
231	
232	  constructor(readonly items: Item[]) {
233	    this.remainingCap = insuranceSum(items) * CAP_FACTOR;
234	  }
235	
236	  payUpToCap(desiredPayout: number): number {
237	    const payout = Math.min(desiredPayout, this.remainingCap);
238	    this.remainingCap -= payout;
239	    return payout;
240	  }
241	}
242	
243	/**
244	 * The policies a scenario has issued. A policy is identified by the index of
245	 * the quote step that created it, and its total payout is capped at twice its
246	 * insurance sum.
247	 */
248	class PolicyRegister {
249	  private readonly policies = new Map<number, Policy>();
250	
251	  issue(stepIndex: number, items: Item[]): void {
252	    this.policies.set(stepIndex, new Policy(items));
253	  }
254	
255	  find(stepIndex: number): Policy {
256	    const policy = this.policies.get(stepIndex);
257	    if (policy === undefined) {
258	      throw new Error(`No policy was created by step ${stepIndex}`);
259	    }
260	    return policy;
261	  }
262	}
263	
264	/**
265	 * Every damage entry refers to one insured item of its type, so a damaged item
266	 * is claimed at most once per incident. A claim naming more items of a type
267	 * than the policy covers is rejected as a whole.
268	 */
269	class InsuredItems {
270	  private readonly unclaimed: Item[];
271	
272	  constructor(items: Item[]) {
273	    this.unclaimed = [...items];
274	  }
275	
276	  claim(itemType: string): Item {
277	    const index = this.unclaimed.findIndex((insured) => insured.type === itemType);
278	    if (index < 0) {
279	      throw new Error(`The policy does not cover a further item of type "${itemType}"`);
280	    }
281	    return this.unclaimed.splice(index, 1)[0];
282	  }
283	}
284	
285	function settleClaim(policy: Policy, incident: Incident): ClaimResult {
286	  const insured = new InsuredItems(policy.items);
287	  incident.damages.forEach(validateDamage);
288	  const desired = incident.damages.reduce(
289	    (sum, damage) => sum + reimbursement(damage, insured.claim(damage.itemType)),
290	    0,
291	  );
292	  const payout = policy.payUpToCap(roundPayout(desired));
293	  return { payout, remainingCap: policy.remainingCap };
294	}
295	
296	export function runScenario(scenario: Scenario): StepResult[] {
297	  const policies = new PolicyRegister();
298	  let contracts = 0;
299	  return scenario.steps.map((step, index) => {
300	    if (step.op === "claim") {
301	      return settleClaim(policies.find(step.policy), step.incident);
302	    }
303	    const premium = quote(step.items, {
304	      customer: scenario.customer,
305	      previousContracts: contracts,
306	    });
307	    contracts += 1;
308	    policies.issue(index, step.items);
309	    return { premium };
310	  });
311	}

